<?php
declare(strict_types=1);
require_once __DIR__.'/_common.php';
require_once APP_ROOT.'/app/Import/ConsolidatedReconciliation.php';
$config=adminConfig('admin');requireDashboardAccess('matches');$db=bmaDatabase($config);$actor=adminReviewActor($db,$config);
if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'){http_response_code(405);header('Allow: GET');exit('Read-only reconciliation preview.');}
header('Cache-Control: private, no-store');
try{$directory=ConsolidatedInputs::directory();$input=ConsolidatedInputs::read($directory,Paths::servedRoots($config));$approvals=[];$file=realpath($directory.'/approvals.json');if($file!==false){Paths::assertPrivate($file,Paths::servedRoots($config));if(filesize($file)>1048576)throw new RuntimeException('APPROVALS_INVALID');$approvals=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);}$p=(new ConsolidatedReconciliation($db))->preview($actor,$input,$approvals,HistoricalPaymentPreview::read($directory,Paths::servedRoots($config)));}
catch(Throwable){http_response_code(503);adminHead('Consolidated reconciliation');echo '<div class="alert alert-warning">The private reconciliation preview is unavailable. No database records were changed.</div>';adminFoot();exit;}
adminHead('Consolidated reconciliation');echo '<h1 class="h3">Consolidated association preview</h1><p>Read-only references to existing sources. CSV evidence does not confirm identities, parentage or membership. Production apply requires separate administrator authorization and a complete database backup.</p><div class="row g-3">';foreach($p['summary'] as $key=>$value)echo '<div class="col-6 col-lg-3"><div class="surface-card card p-3"><strong class="h4">'.e($value).'</strong><span>'.e(str_replace('_',' ',$key)).'</span></div></div>';echo '</div><h2 class="h5 mt-4">Before counts (unchanged by preview)</h2><pre>'.e(json_encode($p['before_counts'],JSON_PRETTY_PRINT)).'</pre><p>Approval digest: <code>'.e($p['digest']).'</code>. This page has no apply action.</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Group</th><th>Student identity</th><th>Outcome</th><th>Review codes</th></tr></thead><tbody>';
foreach($p['groups'] as $g){$person=$p['entities'][$g['student_key']]['person_id']??null;
    echo '<tr><td>'.e($g['group_id']).'</td><td><strong>Student: '.e($p['entities'][$g['student_key']]['name']??'Source name unavailable').'</strong><br>'.($person===null?'One new person proposed if source checks pass':'<a href="/member.php?person='.e($person).'">Existing person profile</a>');
    echo '<details class="mt-2"><summary>Payer / signer evidence and review</summary><p>Waivers: '.e(count($g['waivers'])).' · Payment references: '.e($g['household_payment_references']).'</p>';
    foreach($g['customers'] as $c)echo '<p><strong>Stripe payer:</strong> '.e($c['name']??'Name unavailable').' · <code>'.e($c['stripe_customer_id']).'</code></p>';
    foreach($g['waivers'] as $w)echo '<p><strong>Waiver signer:</strong> '.e($w['signer_print_name']??'Unknown').' · <strong>Stated relationship:</strong> '.e($w['relationship_to_student']??'Unknown').' · source '.e($w['source_record_id']).'</p>';
    echo '<p>Household evidence is proposed, not proof of same identity or legal parentage. Payer account payments may cover other students.</p>';
    foreach($g['review_groups'] as $review)echo '<a class="btn btn-sm btn-outline-primary me-2" href="group-match.php?action=resolve&amp;group='.e(rawurlencode($review)).'">Review / approve payer association</a>';
    if($g['review_groups']===[])echo '<p>No existing review candidate. A separately reviewed private approvals file can select the payer and confirm payer_student_verified; this preview cannot save decisions.</p>';
    echo '</details></td><td>'.e(!$g['ready']?'Identity conflict / needs review':($g['requires_student_approval']?'Eligible person proposal — approval pending':'Validated existing student')).'</td><td>'.e(implode(', ',array_merge($g['issues'],$g['household_issues'],$g['proposals']))).'</td></tr>';
}echo '</tbody></table></div><p>Historical payment preview is read-only. Existing transactions are preserved. Identifier enrichment and absent charge rows are separate proposals; no backfill apply endpoint is implemented. A complete database backup and separate approval are required before any data write.</p>';adminFoot();
